#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
# 形式が違う時刻は exit 2 で断り、stdout に何も出さず、予約を残さない
for args in "9am 10:00" "09:00 10am" "09:00 10:0x"; do
  set -- $args
  out=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 $1 $2 x 2>/dev/null); rc=$?
  [ "$rc" = 2 ] || { echo "bad time $args: exit should be 2, got $rc"; fail=1; }
  [ -z "$out" ] || { echo "bad time $args: stdout should be empty"; fail=1; }
done
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
rm -f "$t"; exit $fail

